/** sha256 of the committed manifest this module was generated from. */
export const MATERIAL_MANIFEST_SHA256 = DATA.manifest.sha256;

/** Roster slugs with a committed runtime material entry, in roster order. */
export const MATERIAL_SLUGS = DATA.slugs;

/**
 * Recovered runtime values only: paint, glass, emissive and alloy. Fields the
 * retail format does not serialize are absent and named in `missing`.
 */
export const MATERIAL_OVERRIDES = deepFreeze(Object.fromEntries(
  DATA.slugs.map((slug) => {
    const car = DATA.cars[slug];
    return [slug, {
      baseColour: car.baseColour,
      glass: car.glass,
      emissive: car.emissive,
      emissiveStrength: car.emissiveStrength,
      alloy: car.alloy,
      missing: car.missing
    }];
  })
));

/**
 * Return the committed runtime material for one roster car.
 *
 * @param {string} slug
 * @returns {{schema:string, slug:string, baseColour:number[],
 *   glass:{tint:number[], minAlpha:number, maxAlpha:number,
 *     minReflectivity:number, maxReflectivity:number,
 *     blend:{src:string, dest:string, alphaTest:boolean}},
 *   emissive:number[], emissiveStrength:number,
 *   alloy:{colour:number[], specPow:number, specInt:number},
 *   missing:Array<{field:string, sourceField:string, present:boolean,
 *     searchedFields:string[], reason:string}>,
 *   source:object}}
 * @throws {CarMaterialError} `invalid-slug` for a non-string slug,
 *   `unknown-slug` for a slug outside the roster.
 */
export function materialsFor(slug) {
  if (typeof slug !== 'string') {
    throw new CarMaterialError('invalid-slug',
      'materialsFor: slug must be a string, got ' + typeof slug);
  }
  const car = DATA.cars[slug];
  if (!car) {
    throw new CarMaterialError('unknown-slug',
      'materialsFor: unknown car slug ' + JSON.stringify(slug) +
      ' (use one of ' + MATERIAL_SLUGS.length + ' roster slugs)');
  }
  return car;
}

export default Object.freeze({
  MATERIAL_SCHEMA,
  MATERIAL_MANIFEST_SHA256,
  MATERIAL_SLUGS,
  MATERIAL_OVERRIDES,
  materialsFor,
  CarMaterialError
});
